// Bridge Fallback Rate Monitor — fetch and aggregate
// Monitora workflows Bridge conhecidos. Para cada exec com Fallback Router node,
// verifica se fallback=true. Reporta total + breakdown por workflow.

const WORKFLOWS = [
  { name: 'KF2 Auditoria SDR', id: 'KF2KP3EEXbhf4iL2', instance: 'railway' },
  { name: 'JoCn SDR TJ', id: 'JoCnFgcrlgOwDU0i', instance: 'railway' },
  { name: 'BGBIQEV SDR CF', id: 'BGBIQEV315w0U5CC', instance: 'railway' },
  { name: 'lbP5 SDR', id: 'lbP5iq38rRwWdr8b', instance: 'hetzner' },
];

// Node names que sao Fallback Router em workflows conhecidos
const FALLBACK_NODE_NAMES = [
  'Fallback Router', 'Fallback Router2', 'Fallback Router SDR',
  'Fallback Router SDR2', 'Fallback Router 2', 'FallbackRouter'
];

const CONFIG = {
  railway: {
    url: 'https://primary-production-af84.up.railway.app',
    key: "n8n_api_7106fcbdbdf4d40033f526389678362013ef6806a543a54bc1cf025bfe8e3f7020363d15e6d31b31"
  },
  hetzner: {
    url: 'http://n8n_editor:5678', // DNS overlay Swarm; URL publico (hairpin CF/Traefik) dava 502 de dentro do worker (fix 2026-07-25),
    key: "***REDACTED***"
  }
};

const SINCE_HOURS = 24;
const sinceMs = Date.now() - SINCE_HOURS * 3600 * 1000;
const results = [];

for (const wf of WORKFLOWS) {
  const cfg = CONFIG[wf.instance];
  const listUrl = cfg.url + '/api/v1/executions?workflowId=' + wf.id + '&limit=25&status=success&includeData=true';
  try {
    const resp = await this.helpers.httpRequest({
      method: 'GET',
      url: listUrl,
      headers: { 'X-N8N-API-KEY': cfg.key },
      json: true,
      timeout: 120000,
    });
    const raw = resp && resp.data ? resp.data : [];
    const recent = raw.filter(e => {
      const t = e.stoppedAt ? new Date(e.stoppedAt).getTime() : 0;
      return t >= sinceMs;
    });
    let fallbacks = 0;
    let executed = 0;
    for (const e of recent) {
      const rd = (e.data && e.data.resultData && e.data.resultData.runData) || {};
      let fbNode = null;
      for (const nm of FALLBACK_NODE_NAMES) {
        if (rd[nm]) { fbNode = rd[nm]; break; }
      }
      if (!fbNode) continue;
      executed++;
      try {
        const j = fbNode[0].data.main[0][0].json;
        if (j && j.fallback === true) fallbacks++;
      } catch(err) { /* skip */ }
    }
    results.push({
      name: wf.name, id: wf.id, instance: wf.instance,
      total_execs: recent.length,
      with_fb_router: executed,
      fallbacks: fallbacks,
      rate_pct: executed > 0 ? Math.round((fallbacks / executed) * 100) : 0,
    });
  } catch(e) {
    results.push({ name: wf.name, id: wf.id, instance: wf.instance, error: (e.message || String(e)).slice(0, 200) });
  }
}

const totalFallbacks = results.reduce((s, r) => s + (r.fallbacks || 0), 0);
const anyErrors = results.filter(r => r.error).length;
const shouldAlert = totalFallbacks > 0 || anyErrors > 0;

return [{ json: { results, totalFallbacks, anyErrors, shouldAlert, since_hours: SINCE_HOURS } }];

// Format Telegram alert
const data = $input.first().json;
const results = data.results || [];

let msg = '🌉 *Bridge Fallback Report — ' + new Date().toISOString().slice(0,10) + '*\n';
msg += '_Ultimas ' + (data.since_hours || 24) + 'h_\n\n';
msg += '*Total fallbacks:* ' + (data.totalFallbacks || 0) + '\n';
if (data.anyErrors) msg += '*Erros ao consultar API:* ' + data.anyErrors + '\n';
msg += '\n*Breakdown:*\n';

for (const r of results) {
  const emoji = r.error ? '❌' : (r.fallbacks > 0 ? '🔴' : '✅');
  if (r.error) {
    msg += emoji + ' ' + r.name + ' — ERRO: ' + r.error.slice(0, 60) + '\n';
  } else {
    msg += emoji + ' ' + r.name + ' (' + r.instance + '): ' + r.fallbacks + '/' + r.with_fb_router + ' fallbacks';
    if (r.rate_pct > 0) msg += ' (' + r.rate_pct + '%)';
    msg += '\n';
  }
}

msg += '\n_Investigar: ssh macmini, logs Bridge, ou payload size dos workflows em fallback_';

return [{ json: { text: msg } }];

